const M = require('/opt/lv/automation/ads/meta-ads.js');
const it = $input.first();
const raw = it.binary && it.binary.data ? Buffer.from(it.binary.data.data, 'base64').toString('utf8') : (it.json.rawBody || JSON.stringify(it.json.body));
const sig = (it.json.headers || {})['x-hub-signature-256'];
if (!M.verifyWebhookSignature(raw, sig, $env.META_APP_SECRET)) throw new Error('bad Meta webhook signature: dropped');
return [{ json: { trigger: 'webhook' } }];

const q = $json.query || {};
const ok = q['hub.mode'] === 'subscribe' && q['hub.verify_token'] === $env.META_WEBHOOK_VERIFY_TOKEN;
return [{ json: { ok, challenge: ok ? String(q['hub.challenge']) : 'forbidden' } }];

const M = require('/opt/lv/automation/ads/meta-ads.js');
const client = M.createClient({ token: $env.META_SYSTEM_USER_TOKEN, apiVersion: $env.META_API_VERSION || 'v23.0', maxInlineWaitMs: 20000 });
const out = [];
for (const it of $input.all()) {
  const b = it.json;
  try {
    const h = await client.getAssetHealth({ businessId: b.business_id, pageId: b.page_id, igUserId: b.ig_user_id, wabaId: b.waba_id, phoneNumberId: b.phone_number_id, adAccountId: b.ad_account_id, pixelId: b.pixel_id });
    const d = M.diffHealth({ waba_quality: b.waba_quality, alerts: b.health_alerts || [] }, h);
    out.push({ json: { brand_id: b.brand_id, ok: true, health: h, urgent: d.urgent, new_alerts: d.new_alerts, templates: (h.template_status && h.template_status.items) || [] } });
  } catch (e) {
    // API error -> retry next run; a rate-limit back-off is not an alert.
    out.push({ json: { brand_id: b.brand_id, ok: false, code: e.code || 'ERR', message: String(e.message).slice(0, 300), urgent: false, retry_after_ms: e.retryAfterMs || null } });
  }
}
return out;

