-- ASSUMPTION: message_templates (name, status, category, rejected_reason, status_synced_at) per the crm-gap "message_templates extension". UPDATE only: submission is submit.sh / meta-operator.
UPDATE message_templates t SET status = x.status, category = x.category, rejected_reason = x.rejected_reason, status_synced_at = now()
FROM jsonb_to_recordset($1::jsonb) AS x(name text, status text, category text, rejected_reason text) WHERE t.name = x.name RETURNING t.name;
